package ama.api;
import org.junit.jupiter.api.Test;import org.springframework.mock.web.MockHttpServletRequest;import java.nio.charset.StandardCharsets;import static org.junit.jupiter.api.Assertions.*;
class Task10SavedWireTest {
 static final String ID="12345678-1234-4234-8234-123456789abc";
 static MockHttpServletRequest request(String body){var r=new MockHttpServletRequest();r.setContent(body.getBytes(StandardCharsets.UTF_8));return r;}
 @Test void exactCountersAndDualFormsNormalizeBeforeDigest()throws Exception{for(String n:new String[]{"9007199254740991","9007199254740992","9007199254740993","9223372036854775806"}){var a=MinutesSavedWire.command(request("{\"expectedRevisionToken\":\""+n+"\"}"),"MINUTES_REJECT",ID);var b=MinutesSavedWire.command(request("{\"expectedRevision\":"+n+",\"expectedRevisionToken\":\""+n+"\"}"),"MINUTES_REJECT",ID);assertEquals(Long.parseLong(n),a.expected());assertEquals(a.expected(),b.expected());assertArrayEquals(a.semantics(),b.semantics());}for(String invalid:new String[]{"-1","01"," 1","1e2","1.0","9223372036854775807"})assertThrows(IllegalArgumentException.class,()->MinutesSavedWire.command(request("{\"expectedRevisionToken\":\""+invalid+"\"}"),"MINUTES_REJECT",ID));assertThrows(IllegalArgumentException.class,()->MinutesSavedWire.command(request("{\"expectedRevision\":1,\"expectedRevisionToken\":\"2\"}"),"MINUTES_REJECT",ID));}
 @Test void strictReviewUnionRejectsInapplicableOffsetsAndScopes(){for(String fields:new String[]{"\"reviewKind\":\"ACTION_FIELDS\",\"scope\":null,\"outcome\":\"CONFIRMED\",\"startToken\":\"0\",\"endToken\":\"1\"","\"reviewKind\":\"ACTION_FIELDS\",\"scope\":\"WHOLE\",\"outcome\":\"CONFIRMED\"","\"reviewKind\":\"SOURCE_SUPPORT\",\"scope\":\"WHOLE\",\"outcome\":\"SUPPORTED\",\"startToken\":\"0\",\"endToken\":\"1\"","\"reviewKind\":\"SOURCE_SUPPORT\",\"scope\":\"SPAN\",\"outcome\":\"SUPPORTED\"","\"reviewKind\":\"SOURCE_SUPPORT\",\"scope\":null,\"outcome\":\"CONFIRMED\""})assertThrows(IllegalArgumentException.class,()->MinutesSavedWire.command(request("{\"expectedRevisionToken\":\"1\",\"target\":{\"kind\":\"ELEMENT\",\"id\":\""+ID+"\"},"+fields+"}"),"MINUTES_REVIEW",null),fields);}
 @Test void duplicateUnknownAndTrailingDocumentsFail(){for(String text:new String[]{"{\"operation\":\"MINUTES_ADOPT\",\"operation\":\"MINUTES_REJECT\",\"key\":\"x\"}","{\"operation\":\"MINUTES_ADOPT\",\"key\":\"x\",\"extra\":null}","{\"operation\":\"MINUTES_ADOPT\",\"key\":\"x\"}{}"})assertThrows(IllegalArgumentException.class,()->MinutesSavedWire.discovery(request(text)));}
 @Test void nullableActionTupleRequiresAllThreeMembers()throws Exception{String prefix="{\"expectedRevisionToken\":\"1\",\"sourceSetId\":\""+ID+"\",";var command=MinutesSavedWire.command(request(prefix+"\"ownerEnterpriseId\":null,\"ownerDisplay\":null,\"dueOn\":null}"),"MINUTES_ACTION_FIELDS",ID);assertNull(command.semantics()[3]);assertNull(command.semantics()[4]);assertNull(command.semantics()[5]);assertThrows(IllegalArgumentException.class,()->MinutesSavedWire.command(request(prefix+"\"ownerEnterpriseId\":null,\"ownerDisplay\":null}"),"MINUTES_ACTION_FIELDS",ID));}
}
